-- S78.2 (ADR-0071 §S78.2): `booking.release` on the dial and the `release_check` reminder, the
-- owner's release card at the confirm cut-off.
ALTER TABLE "ai_action_executions" DROP CONSTRAINT "ai_action_executions_action_known";--> statement-breakpoint
ALTER TABLE "ai_action_proposals" DROP CONSTRAINT "ai_action_proposals_action_known";--> statement-breakpoint
ALTER TABLE "autonomy_settings" DROP CONSTRAINT "autonomy_settings_levels_known";--> statement-breakpoint
ALTER TABLE "booking_reminders" DROP CONSTRAINT "booking_reminders_kind_known";--> statement-breakpoint
ALTER TABLE "ai_action_executions" ADD CONSTRAINT "ai_action_executions_action_known" CHECK ("ai_action_executions"."action" IN ('booking.create', 'booking.move', 'booking.cancel', 'booking.no_show', 'booking.release', 'booking_request.accept', 'time.block', 'client_note.save', 'rule.change', 'task.create', 'waitlist.change', 'message.confirmation', 'message.rebooking_nudge', 'message.waitlist_offer', 'message.bulk', 'message.review_request', 'message.client', 'payment.no_show_fee'));--> statement-breakpoint
ALTER TABLE "ai_action_proposals" ADD CONSTRAINT "ai_action_proposals_action_known" CHECK ("ai_action_proposals"."action" IN ('booking.create', 'booking.move', 'booking.cancel', 'booking.no_show', 'booking.release', 'booking_request.accept', 'time.block', 'client_note.save', 'rule.change', 'task.create', 'waitlist.change', 'message.confirmation', 'message.rebooking_nudge', 'message.waitlist_offer', 'message.bulk', 'message.review_request', 'message.client', 'payment.no_show_fee'));--> statement-breakpoint
ALTER TABLE "autonomy_settings" ADD CONSTRAINT "autonomy_settings_levels_known" CHECK (jsonb_typeof("autonomy_settings"."levels") = 'object' AND "autonomy_settings"."levels" - ARRAY['booking.create', 'booking.move', 'booking.cancel', 'booking.no_show', 'booking.release', 'booking_request.accept', 'time.block', 'client_note.save', 'rule.change', 'task.create', 'waitlist.change', 'message.confirmation', 'message.rebooking_nudge', 'message.waitlist_offer', 'message.bulk', 'message.review_request', 'message.client', 'payment.no_show_fee'] = '{}'::jsonb AND NOT jsonb_path_exists("autonomy_settings"."levels", '$.* ? (@ != "ask" && @ != "notify" && @ != "auto")'));--> statement-breakpoint
ALTER TABLE "booking_reminders" ADD CONSTRAINT "booking_reminders_kind_known" CHECK ("booking_reminders"."kind" IN ('confirm_ask', 'day_before', 'same_day', 'release_check'));